using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Windows.Forms;
using System.Threading;
using VirgilPatch;
class DiagnosticsTests {
 static string root; static int passed;
 static void Assert(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Test(string name,Action run){run();passed++;Console.WriteLine("PASS "+name);}
 static State Fresh(){var area=Path.Combine(root,Guid.NewGuid().ToString("N"),"PrivateAlice","SensitiveProject");Config.StateDir=Path.Combine(area,"state");var s=new State{patches_dir=Path.Combine(area,"Epsilon","Epsilon","_retail_","Patches")};Directory.CreateDirectory(s.patches_dir);return s;}
 static void Private(string value){foreach(string bad in new[]{"PrivateAlice","SensitiveProject","private@example.com","secret-token","ServerSecret","PrivateShare"})Assert(!value.Contains(bad),"Private content leaked: "+bad);}
 [STAThread] static int Main(string[] args){try{root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Application.EnableVisualStyles();Config.StartAmbienceMuted=true;
 Test("personal-paths-redacted-but-repeated-epsilon-levels-preserved",delegate{var s=Fresh();var report=new PatchDiagnostics().Build(s,null,false);Private(report);Assert(report.Contains(@"Epsilon\Epsilon\_retail_\Patches"),"Structure lost");Assert(!report.Contains(Path.GetPathRoot(s.patches_dir)),"Drive exposed");});
 Test("path-tokens-are-consistent-within-report-and-distinguish-roots",delegate{var r=new PatchDiagnostics.Redactor();string a=r.Path(@"E:\PrivateAlice\Epsilon\_retail_\Patches"),b=r.Path(@"E:\PrivateAlice\Epsilon\Epsilon\_retail_\Patches"),c=r.Path(@"F:\PrivateAlice\Epsilon\_retail_\Patches");Private(a+b+c);Assert(a!=b&&a!=c&&r.Path(@"E:\PrivateAlice\Epsilon\_retail_\Patches")==a,"Locations ambiguous");});
 Test("network-server-and-share-never-leak",delegate{var r=new PatchDiagnostics.Redactor();var x=r.Path(@"\\ServerSecret\PrivateShare\PrivateAlice\Epsilon\_retail_\Patches");Private(x);Assert(x.Contains("_retail_"),"Structure absent");});
 Test("arbitrary-folder-and-metadata-names-are-redacted",delegate{var s=Fresh();Directory.CreateDirectory(Path.Combine(s.patches_dir,"private@example.com"));string p=Path.Combine(s.patches_dir,"!Chronicles-TexturePatch(4.0.0)");Directory.CreateDirectory(p);File.WriteAllText(Path.Combine(p,"patch.json"),"{\"name\":\"secret-token\",\"version\":\"PrivateAlice\",\"files\":[]}");var x=new PatchDiagnostics().Build(s,null,false);Private(x);Assert(x.Contains("!Chronicles-TexturePatch(4.0.0)")&&x.Contains("nonstandard or unknown"),"Useful metadata lost");});
 Test("rename-errors-show-category-code-and-redacted-endpoints",delegate{var s=Fresh();var d=new PatchDiagnostics();d.Record("rename started","!Chronicles-TexturePatch(3.2.0)",Path.Combine(s.patches_dir,"!Chronicles-TexturePatch(4.0.0)"),Path.Combine(s.patches_dir,"!Chronicles-TexturePatch(5.0.0)"));d.Record("patch failed",null,s.patches_dir,null,new UnauthorizedAccessException("private@example.com secret-token PrivateAlice"));var x=d.Build(s,null,false);Private(x);Assert(x.Contains("rename started")&&x.Contains("access denied")&&x.Contains("HRESULT"),"Error context missing");});
 Test("untrusted-event-labels-and-commit-values-cannot-leak",delegate{var s=Fresh();var d=new PatchDiagnostics();d.Record("private@example.com", "PrivateAlice",null,null,new IOException("secret-token"));d.Catalog(new Plan{Commit="secret-token"});Private(d.Build(s,null,false));});
 Test("diagnostics-are-read-only-and-do-not-scan-asset-content",delegate{var s=Fresh();string p=Path.Combine(s.patches_dir,"!Chronicles-TexturePatch(4.0.0)");Directory.CreateDirectory(p);string file=Path.Combine(p,"locked.ogg");File.WriteAllText(file,"secret-token");var before=Directory.GetFiles(Path.GetDirectoryName(s.patches_dir),"*",SearchOption.AllDirectories);using(var locked=new FileStream(file,FileMode.Open,FileAccess.ReadWrite,FileShare.None))Private(new PatchDiagnostics().Build(s,null,false));Assert(before.SequenceEqual(Directory.GetFiles(Path.GetDirectoryName(s.patches_dir),"*",SearchOption.AllDirectories)),"Diagnostics changed files");});
 Test("nearby-parent-installation-is-reported-without-switching-root",delegate{var s=Fresh();string parent=Directory.GetParent(Directory.GetParent(Directory.GetParent(s.patches_dir).FullName).FullName).FullName;string other=Path.Combine(parent,"_retail_","Patches");Directory.CreateDirectory(other);string selected=s.patches_dir;var x=new PatchDiagnostics().Build(s,null,false);Private(x);Assert(x.Contains("[other]")&&s.patches_dir==selected,"Nearby install not identified or root switched");});
 Test("history-is-bounded-to-256-events",delegate{var s=Fresh();var d=new PatchDiagnostics();for(int i=0;i<300;i++)d.Record("check cancelled");var x=d.Build(s,null,false);Assert(x.Split(new[]{"  check cancelled"},StringSplitOptions.None).Length-1==256,"History unbounded");});
 Test("missing-folder-inspection-is-safe-and-private",delegate{var s=Fresh();Directory.Delete(s.patches_dir);var x=new PatchDiagnostics().Build(s,null,false);Private(x);Assert(x.Contains("Root exists: False")&&x.Contains("Folder inspection:"),"Missing-root diagnostic absent");Assert(!Directory.Exists(s.patches_dir),"Diagnostics created missing folder");});
 Test("copy-button-uses-redacted-report-without-patch-requests",delegate{var s=Fresh();s.Save();var source=new LauncherFixtureSource();source.Publish("fixture");using(var form=new MainForm(source,null,true)){string copied=null;form.CopyDiagnosticText=x=>copied=x;var button=form.Controls.OfType<Button>().Single(b=>b.Text=="Copy diagnostics");using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=delegate{timer.Stop();button.PerformClick();using(var bitmap=new System.Drawing.Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new System.Drawing.Rectangle(System.Drawing.Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(root,"copy-diagnostics-ui.png"));}form.Close();};timer.Start();Application.Run(form);}Assert(copied!=null&&copied.Contains("Virgil updater diagnostics"),"Button failed");Private(copied);Assert(source.Reads==0&&source.Downloads.Count==0,"Copy initiated patch requests");}});
 Test("copy-clipboard-failure-is-contained",delegate{var s=Fresh();s.Save();using(var form=new MainForm(new LauncherFixtureSource(),null,true)){form.CopyDiagnosticText=x=>{throw new IOException("secret-token");};typeof(MainForm).GetMethod("CopyDiagnostics",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null);Assert(!form.DiagnosticText().Contains("secret-token"),"Clipboard exception leaked");}});
 Console.WriteLine("TOTAL "+passed+" privacy/diagnostics cases passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
